class Solution {
  private static int gcd(int a, int b) {
    while (b != 0) {
      int t = a % b;
      a = b;
      b = t;
    }
    return a;
  }

  public int countTrapezoids(int[][] points) {
    int n = points.length, m = n * (n - 1) / 2;
    long[] lineKeys = new long[m], midKeys = new long[m];
    int idx = 0;
    for (int i = 0; i < n; i++) {
      for (int j = i + 1; j < n; j++) {
        int dx = points[j][0] - points[i][0], dy = points[j][1] - points[i][1];
        int g = gcd(Math.abs(dx), Math.abs(dy));
        dx /= g;
        dy /= g;
        if (dx < 0 || (dx == 0 && dy < 0)) {
          dx = -dx;
          dy = -dy;
        }
        long dir = (long) (dx + 2000) * 4001 + (dy + 2000);
        long c = (long) dx * points[i][1] - (long) dy * points[i][0];
        lineKeys[idx] = dir * 20_000_000L + (c + 10_000_000L);
        long mid =
            (long) (points[i][0] + points[j][0] + 2000) * 4001
                + (points[i][1] + points[j][1] + 2000);
        midKeys[idx] = mid * 16_100_000L + dir;
        idx++;
      }
    }
    java.util.Arrays.sort(lineKeys);
    java.util.Arrays.sort(midKeys);
    long pairs = 0;
    for (int i = 0; i < m; ) {
      long dir = lineKeys[i] / 20_000_000L;
      int j = i;
      long total = 0, same = 0;
      while (j < m && lineKeys[j] / 20_000_000L == dir) {
        int k = j;
        while (k < m && lineKeys[k] == lineKeys[j]) k++;
        long c = k - j;
        same += c * (c - 1) / 2;
        total += c;
        j = k;
      }
      pairs += total * (total - 1) / 2 - same;
      i = j;
    }
    long parallelograms = 0;
    for (int i = 0; i < m; ) {
      long mid = midKeys[i] / 16_100_000L;
      int j = i;
      long total = 0, same = 0;
      while (j < m && midKeys[j] / 16_100_000L == mid) {
        int k = j;
        while (k < m && midKeys[k] == midKeys[j]) k++;
        long c = k - j;
        same += c * (c - 1) / 2;
        total += c;
        j = k;
      }
      parallelograms += total * (total - 1) / 2 - same;
      i = j;
    }
    return (int) (pairs - parallelograms);
  }
}
